        })
        .map(function (produto) {
            return {
                id: produto.id,
                titulo: produto.title,
                preco: produto.price
            };
        });

    console.log(
        "RELATÓRIO DE PRODUTOS COM PREÇO INVÁLIDO:\n" +
        JSON.stringify(produtosInvalidos, null, 2)
    );  

    pm.expect(produtosInvalidos.length).to.equal(0);
});

