pm.test("CT-API-019 - Validar integridade dos campos essenciais de todos os produtos", function () {

    const resposta = pm.response.json();
    const inconsistencias = [];
    let quantidadeAnalisada = 0;

    // Validar estrutura da resposta
    if (!Array.isArray(resposta.products)) {
        inconsistencias.push({
            erro: "A resposta não contém um array de produtos."
        });
    } else {

        const produtos = resposta.products;
        quantidadeAnalisada = produtos.length;

        // Validar quantidade total de produtos
        if (!Number.isInteger(resposta.total) || resposta.total < 0) {
            inconsistencias.push({
                erro: "Campo total ausente ou inválido."
            });
        } else if (produtos.length !== resposta.total) {
            inconsistencias.push({
                erro: "Quantidade retornada diferente do total informado pela API.",
                quantidadeRetornada: produtos.length,
                totalInformado: resposta.total
            });
        }

        // Percorrer todos os produtos
        produtos.forEach(function (produto, indice) {

            const id = produto && produto.id !== undefined
                ? produto.id
                : "Não identificado";

            function registrarInconsistencia(campo, problema) {
                inconsistencias.push({
                    produtoID: id,
                    posicao: indice + 1,
                    campo: campo,
                    problema: problema
                });
            }

            if (!produto || typeof produto !== "object" || Array.isArray(produto)) {
                registrarInconsistencia("produto", "Estrutura inválida.");
                return;
            }

            // Validar presença e integridade do ID
            if (!Number.isInteger(produto.id) || produto.id <= 0) {
                registrarInconsistencia("id", "Deve ser um número inteiro positivo.");
            }

            // Validar campos de texto
            ["title", "description", "category", "thumbnail"].forEach(function (campo) {

                if (typeof produto[campo] !== "string" || produto[campo].trim() === "") {
                    registrarInconsistencia(campo, "Deve ser uma string não vazia.");
                }

            });

            // Validar preço
            if (typeof produto.price !== "number" || !Number.isFinite(produto.price) || produto.price <= 0) {
                registrarInconsistencia("price", "Deve ser um número maior que zero.");
            }

            // Validar array de imagens
            if (!Array.isArray(produto.images) || produto.images.length === 0) {
                registrarInconsistencia("images", "Deve ser um array não vazio.");
            } else {

                produto.images.forEach(function (imagem, indiceImagem) {

                    if (typeof imagem !== "string" || imagem.trim() === "") {
                        registrarInconsistencia(
                            "images[" + indiceImagem + "]",
                            "Deve ser uma string não vazia."
                        );
                    }

                });

            }

        });

    }

    // Consolidar resultados
    console.log("RELATÓRIO CT-API-019");
    console.log("Produtos analisados:", quantidadeAnalisada);
    console.log("Total de inconsistências:", inconsistencias.length);

    if (inconsistencias.length > 0) {
        console.table(inconsistencias);
    } else {
        console.log("Todos os produtos atenderam aos critérios de validação.");
    }

    pm.expect(
        inconsistencias,
        "Foram identificadas inconsistências: " +
        JSON.stringify(inconsistencias, null, 2)
    ).to.have.lengthOf(0);

});
